local VERSION='8.0.0'
local escalations, duplicateFingerprints, recommendations = {}, {}, {}
local function uid(prefix)return('%s-%s-%04d'):format(prefix,os.time(),math.random(0,9999))end
exports('DetectDuplicateMedicalCall',function(data)data=type(data)=='table'and data or{};local c=data.coords or{};local fingerprint=('%s:%s:%s:%s'):format(math.floor((tonumber(c.x)or 0)/25),math.floor((tonumber(c.y)or 0)/25),tostring(data.type or'medical'),math.floor(os.time()/90));local existing=duplicateFingerprints[fingerprint];if existing then return true,existing end;duplicateFingerprints[fingerprint]=data.id or uid('CALL');return false,duplicateFingerprints[fingerprint] end)
exports('RecommendMedicalResponse',function(clinical,availability)clinical=type(clinical)=='table'and clinical or{};availability=type(availability)=='table'and availability or{};local units={'ambulance'};if(tonumber(clinical.precisionRisk)or 0)>=70 then units[#units+1]='ems_supervisor';units[#units+1]='critical_care' end;if clinical.entrapment then units[#units+1]='fire_rescue' end;local item={id=uid('RESP'),units=units,priority=(tonumber(clinical.precisionRisk)or 0)>=70 and 1 or 2,availability=availability,createdAt=os.time()};recommendations[item.id]=item;return item end)
exports('EscalateMedicalCall',function(callId,reason,priority,actor)local item={id=uid('ESC'),callId=callId,reason=reason,priority=tonumber(priority)or 1,actor=actor,createdAt=os.time()};escalations[item.id]=item;TriggerEvent('dpn-medical:dispatch:callEscalated',item);return item.id,item end)
exports('GetDispatchV8Board',function()return{escalations=escalations,responseRecommendations=recommendations,duplicates=duplicateFingerprints,generatedAt=os.time()}end)
CreateThread(function()Wait(3000);pcall(function()exports['dpn-medical-core']:RegisterModule('dpn-medical-dispatch',VERSION,{'duplicate_detection','resource_recommendation','call_escalation','dispatch_resilience'})end);print('[dpn-medical-dispatch] v8 intelligent response and duplicate prevention active')end)
